UNITS = [{'id': 'PEDS-U057', 'ch': 7, 'n': 1, 'title': 'Neonatal Reflexes — Primitive Reflexes Table', 'sec': 'Neonatal reflexes · p30', 'qs': ['PEDS-C7-001', 'PEDS-C7-002', 'PEDS-C7-003', 'PEDS-C7-004', 'PEDS-C7-005', 'PEDS-C7-006', 'PEDS-C7-007', 'PEDS-C7-008', 'PEDS-C7-009', 'PEDS-C7-010', 'PEDS-C7-011', 'PEDS-C7-012', 'PEDS-C7-013', 'PEDS-C7-014', 'PEDS-C7-015', 'PEDS-C7-016', 'PEDS-C7-017', 'PEDS-C7-018', 'PEDS-C7-019', 'PEDS-C7-020', 'PEDS-C7-021', 'PEDS-C7-022', 'PEDS-C7-023', 'PEDS-C7-024'], 'guide': 'Primitive (immature) reflexes disappear after birth. Palmar grasp 28w→32w→2-3m, Rooting 28-32w→34-36w→<1m prominent (finds nipple), Moro 28-32w→37w→5-6m, ATNR 35w→1m postnatal→6-7m.'}, {'id': 'PEDS-U058', 'ch': 7, 'n': 2, 'title': 'Moro Reflex — Abnormalities', 'sec': 'Moro reflex – Abnormalities · p30', 'qs': ['PEDS-C7-025', 'PEDS-C7-026', 'PEDS-C7-027', 'PEDS-C7-028', 'PEDS-C7-029', 'PEDS-C7-030', 'PEDS-C7-031', 'PEDS-C7-032', 'PEDS-C7-033', 'PEDS-C7-034', 'PEDS-C7-035', 'PEDS-C7-036', 'PEDS-C7-037'], 'guide': 'Absent in term = brain structural/functional (anencephaly, HIE). Sluggish = hypotonia (metabolic, Down, SMA). Unilateral = limb pathology: nerve (Erb’s/Klumpke) vs bone (clavicle fracture m/c).'}, {'id': 'PEDS-U059', 'ch': 7, 'n': 3, 'title': 'Postnatal Reflexes — SPL', 'sec': 'Postnatal reflexes · p31', 'qs': ['PEDS-C7-038', 'PEDS-C7-039', 'PEDS-C7-040', 'PEDS-C7-041', 'PEDS-C7-042', 'PEDS-C7-043', 'PEDS-C7-044', 'PEDS-C7-045', 'PEDS-C7-046', 'PEDS-C7-047', 'PEDS-C7-048', 'PEDS-C7-049', 'PEDS-C7-050', 'PEDS-C7-051', 'PEDS-C7-052', 'PEDS-C7-053', 'PEDS-C7-054', 'PEDS-C7-055', 'PEDS-C7-056'], 'guide': 'Appear after birth; mnemonic SPL (Special). STNR 4-6m→8-12m, Parachute 7-8m→never disappears (forward protective extension), Landau 3m→≤9m; ventral suspension, prone and tilt tests.'}, {'id': 'PEDS-U060', 'ch': 7, 'n': 4, 'title': 'Birth Asphyxia and HIE — Definitions', 'sec': 'Birth asphyxia and HIE · p31', 'qs': ['PEDS-C7-057', 'PEDS-C7-058', 'PEDS-C7-059', 'PEDS-C7-060', 'PEDS-C7-061', 'PEDS-C7-062', 'PEDS-C7-063', 'PEDS-C7-064', 'PEDS-C7-065', 'PEDS-C7-066', 'PEDS-C7-067', 'PEDS-C7-068', 'PEDS-C7-069', 'PEDS-C7-070', 'PEDS-C7-071', 'PEDS-C7-072', 'PEDS-C7-073'], 'guide': 'WHO: failure to initiate/sustain breathing. NNF: APGAR 1-min moderate 4-6/10, severe 0-3/10. AAP essential: cord pH<7, APGAR 0-3 at 5-min, neurologic HIE signs, multi-organ (oliguria, ↑LFT). AKA perinatal asphyxia/depression.'}, {'id': 'PEDS-U061', 'ch': 7, 'n': 5, 'title': 'Hypoxic Ischemic Encephalopathy — Sarnat Staging', 'sec': 'Hypoxic ischemic encephalopathy · p31', 'qs': ['PEDS-C7-074', 'PEDS-C7-075', 'PEDS-C7-076', 'PEDS-C7-077', 'PEDS-C7-078', 'PEDS-C7-079', 'PEDS-C7-080', 'PEDS-C7-081', 'PEDS-C7-082', 'PEDS-C7-083', 'PEDS-C7-084', 'PEDS-C7-085', 'PEDS-C7-086', 'PEDS-C7-087', 'PEDS-C7-088', 'PEDS-C7-089', 'PEDS-C7-090', 'PEDS-C7-091', 'PEDS-C7-092', 'PEDS-C7-093'], 'guide': 'HIE = leading neonatal brain injury worldwide; Birth asphyxia→Hypoxia→Ischemia. Sarnat & Sarnat staging: Stage1 99% normal (irritable, mydriasis, normal EEG), Stage2 80% recovery (lethargic, miosis, seizures), Stage3 50% death (comatose, burst-suppression).'}, {'id': 'PEDS-U062', 'ch': 7, 'n': 6, 'title': 'HIE — Complications and Investigations', 'sec': 'Complications · p32', 'qs': ['PEDS-C7-094', 'PEDS-C7-095', 'PEDS-C7-096', 'PEDS-C7-097', 'PEDS-C7-098', 'PEDS-C7-099', 'PEDS-C7-100', 'PEDS-C7-101', 'PEDS-C7-102', 'PEDS-C7-103', 'PEDS-C7-104'], 'guide': 'Term: parasagittal→spastic quadriplegia, focal necrosis→hemiplegic CP, basal ganglia→dystonic/extrapyramidal (chorea/athetosis). Preterm: PVL→spastic diplegia (lower limbs). IOC: DWI MRI. + intellectual disability.'}, {'id': 'PEDS-U063', 'ch': 7, 'n': 7, 'title': 'HIE — Management and Therapeutic Hypothermia', 'sec': 'Management · p32', 'qs': ['PEDS-C7-105', 'PEDS-C7-106', 'PEDS-C7-107', 'PEDS-C7-108', 'PEDS-C7-109', 'PEDS-C7-110', 'PEDS-C7-111', 'PEDS-C7-112', 'PEDS-C7-113', 'PEDS-C7-114', 'PEDS-C7-115', 'PEDS-C7-116', 'PEDS-C7-117', 'PEDS-C7-118'], 'guide': 'Supportive: temp, vitals, glucose 75-100 mg/dL neuroprotective, phenobarbitone for seizures. Therapeutic hypothermia: 33.5-34.5°C, start ≤6h stop ≤72h, Stage2/3 >36wks; preterm <36w C/I; whole-body better than selective head; ↓metabolism→↓free radicals.'}, {'id': 'PEDS-U064', 'ch': 7, 'n': 8, 'title': 'Neonatal Seizures — Types and Etiology', 'sec': 'Neonatal seizures · p34', 'qs': ['PEDS-C7-119', 'PEDS-C7-120', 'PEDS-C7-121', 'PEDS-C7-122', 'PEDS-C7-123', 'PEDS-C7-124', 'PEDS-C7-125', 'PEDS-C7-126', 'PEDS-C7-127', 'PEDS-C7-128', 'PEDS-C7-129', 'PEDS-C7-130', 'PEDS-C7-131', 'PEDS-C7-132', 'PEDS-C7-133'], 'guide': 'Types: Subtle m/c (minimal: blinking/finger rolling/lip chewing), focal clonic best prognosis, myoclonic worst. Etiology: HIE m/c (<24h onset), metabolic (hypoglycemia m/c, hypocalcemia 2nd in IDM), sepsis, bleeds, kernicterus, PVH/germinal matrix.'}, {'id': 'PEDS-U065', 'ch': 7, 'n': 9, 'title': 'Neonatal Seizures — Management and Pyridoxine Trial', 'sec': 'Management · p34', 'qs': ['PEDS-C7-134', 'PEDS-C7-135', 'PEDS-C7-136', 'PEDS-C7-137', 'PEDS-C7-138', 'PEDS-C7-139', 'PEDS-C7-140', 'PEDS-C7-141', 'PEDS-C7-142', 'PEDS-C7-143', 'PEDS-C7-144', 'PEDS-C7-145', 'PEDS-C7-146', 'PEDS-C7-147', 'PEDS-C7-148', 'PEDS-C7-149'], 'guide': 'Stabilize ABC + correct reversible (hypoglycemia <45 → 2mL/kg 10% dextrose). Drugs: phenobarbitone → phenytoin/levetiracetam → midazolam infusion; pyridoxine therapeutic trial ↑GABA via GAD + pyridoxal phosphate.'}]

